1	import charRegex from 'char-regex';
2	import { stripVTControlCharacters } from 'node:util';
3	
4	const SEPARATOR = '  ';
5	
6	function stringLength(string) {
7	  if (!string) {
8	    return 0;
9	  }
10	  const stringWithoutAnsi = stripVTControlCharacters(string);
11	  if (!stringWithoutAnsi) {
12	    return 0;
13	  }
14	  const stringWithSplitEmojis = stringWithoutAnsi.match(charRegex());
15	  if (!stringWithSplitEmojis) {
16	    return 0;
17	  }
18	  return stringWithSplitEmojis.length;
19	}
