import { getAllInstances } from '@clevercloud/client/esm/api/v2/application.js';
import { formatTable } from '../../format-table.js';
import { defineCommand } from '../../lib/define-command.js';
import { styleText } from '../../lib/style-text.js';
import { Logger } from '../../logger.js';
import * as Application from '../../models/application.js';
import { sendToApi } from '../../models/send-to-api.js';
import { aliasOption, appIdOrNameOption, humanJsonOutputFormatOption } from '../global.options.js';

export const instancesCommand = defineCommand({
  description: 'List the instances of an application',
  since: null,
  options: {
    alias: aliasOption,
    app: appIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [],
  async handler(options) {
    const { alias, app: appIdOrName, format } = options;
    const { ownerId, appId } = await Application.resolveId(appIdOrName, alias);

    const instances = await getAllInstances({ id: ownerId, appId }).then(sendToApi);

    switch (format) {
      case 'json': {
        Logger.printJson(
          instances.map((instance) => ({
            id: instance.id,
            state: instance.state,
            flavor: instance.flavor?.name,
            commit: instance.commit,
            deployNumber: instance.deployNumber,
            instanceNumber: instance.instanceNumber,
            isBuildVm: instance.isBuildVm,
            creationDate: instance.creationDate,
          })),
        );
        break;
      }
      case 'human':
      default: {
        if (instances.length === 0) {
          Logger.println('No instance is running for this application');
          break;
        }
        const rows = instances.map((instance) => [
          styleText('bold', instance.id),
          instance.state,
          instance.flavor?.name ?? '',
          instance.commit ?? 'N/A',
          instance.isBuildVm ? 'build' : 'run',
        ]);
        Logger.println(formatTable(rows));
      }
    }
  },
});
